CREATE TABLE public.client_commercial_defaults(client_id uuid PRIMARY KEY,tenant_id uuid NOT NULL,terms jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),created_by uuid,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid,version integer NOT NULL DEFAULT 1,FOREIGN KEY(tenant_id,client_id) REFERENCES public.clients(tenant_id,id));
GRANT SELECT,INSERT,UPDATE ON public.client_commercial_defaults TO authenticated; GRANT ALL ON public.client_commercial_defaults TO service_role;
ALTER TABLE public.client_commercial_defaults ENABLE ROW LEVEL SECURITY;
CREATE POLICY defaults_access ON public.client_commercial_defaults FOR ALL TO authenticated USING(coalesce(public.has_commercial_access(tenant_id),false)) WITH CHECK(coalesce(public.has_commercial_access(tenant_id),false));
CREATE TABLE public.project_appointments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,project_id uuid NOT NULL,contracting_client_id uuid NOT NULL,invoicing_client_id uuid NOT NULL,title text NOT NULL CHECK(length(btrim(title)) BETWEEN 1 AND 200),scope text NOT NULL DEFAULT '',starts_on date,ends_on date,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','active','on_hold','archived')),planning_software text NOT NULL DEFAULT '',construction_contract text NOT NULL DEFAULT '',appointment_basis text NOT NULL DEFAULT '',execution_status text NOT NULL DEFAULT 'pending' CHECK(execution_status IN('pending','unsigned','executed')),document_file_id uuid,document_version integer,stages jsonb NOT NULL DEFAULT '[]',identity_snapshot jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),created_by uuid,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid,version integer NOT NULL DEFAULT 1,UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,project_id) REFERENCES public.projects(tenant_id,id),FOREIGN KEY(tenant_id,contracting_client_id) REFERENCES public.clients(tenant_id,id),FOREIGN KEY(tenant_id,invoicing_client_id) REFERENCES public.clients(tenant_id,id),FOREIGN KEY(tenant_id,document_file_id) REFERENCES public.project_files(tenant_id,id),CHECK(ends_on IS NULL OR starts_on IS NULL OR ends_on>=starts_on),CHECK((document_file_id IS NULL)=(document_version IS NULL)));
GRANT SELECT,INSERT,UPDATE ON public.project_appointments TO authenticated; GRANT ALL ON public.project_appointments TO service_role;
ALTER TABLE public.project_appointments ENABLE ROW LEVEL SECURITY;
CREATE POLICY appointments_read ON public.project_appointments FOR SELECT TO authenticated USING(public.can_view_project(tenant_id,project_id));
CREATE POLICY appointments_insert ON public.project_appointments FOR INSERT TO authenticated WITH CHECK(public.can_manage_project(tenant_id,project_id));
CREATE POLICY appointments_update ON public.project_appointments FOR UPDATE TO authenticated USING(public.can_manage_project(tenant_id,project_id)) WITH CHECK(public.can_manage_project(tenant_id,project_id));
CREATE TABLE public.appointment_commercials(appointment_id uuid PRIMARY KEY,tenant_id uuid NOT NULL,terms jsonb NOT NULL DEFAULT '{}',agreed_fee numeric CHECK(agreed_fee>=0),charging_basis text NOT NULL DEFAULT '',defaults_version integer,defaults_confirmed boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid,version integer NOT NULL DEFAULT 1,FOREIGN KEY(tenant_id,appointment_id) REFERENCES public.project_appointments(tenant_id,id));
GRANT SELECT,INSERT,UPDATE ON public.appointment_commercials TO authenticated; GRANT ALL ON public.appointment_commercials TO service_role;
ALTER TABLE public.appointment_commercials ENABLE ROW LEVEL SECURITY;
CREATE POLICY appointment_money_read ON public.appointment_commercials FOR SELECT TO authenticated USING(coalesce(public.has_commercial_access(tenant_id),false) AND EXISTS(SELECT 1 FROM public.project_appointments a WHERE a.id=appointment_id AND public.can_view_project(a.tenant_id,a.project_id)));
CREATE POLICY appointment_money_insert ON public.appointment_commercials FOR INSERT TO authenticated WITH CHECK(coalesce(public.has_commercial_access(tenant_id),false) AND EXISTS(SELECT 1 FROM public.project_appointments a WHERE a.id=appointment_id AND public.can_manage_project(a.tenant_id,a.project_id)));
CREATE POLICY appointment_money_update ON public.appointment_commercials FOR UPDATE TO authenticated USING(coalesce(public.has_commercial_access(tenant_id),false) AND EXISTS(SELECT 1 FROM public.project_appointments a WHERE a.id=appointment_id AND public.can_manage_project(a.tenant_id,a.project_id))) WITH CHECK(coalesce(public.has_commercial_access(tenant_id),false) AND EXISTS(SELECT 1 FROM public.project_appointments a WHERE a.id=appointment_id AND public.can_manage_project(a.tenant_id,a.project_id)));
CREATE TABLE public.appointment_contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,appointment_id uuid NOT NULL,contact_id uuid NOT NULL,role text NOT NULL CHECK(role IN('project','commercial','fee_approver','timesheet_approver','invoice_approver','accounts_payable','payment_escalation')),created_at timestamptz NOT NULL DEFAULT now(),created_by uuid,UNIQUE(appointment_id,role),FOREIGN KEY(tenant_id,appointment_id) REFERENCES public.project_appointments(tenant_id,id),FOREIGN KEY(tenant_id,contact_id) REFERENCES public.client_contacts(tenant_id,id));
GRANT SELECT,INSERT,DELETE ON public.appointment_contacts TO authenticated; GRANT ALL ON public.appointment_contacts TO service_role;
ALTER TABLE public.appointment_contacts ENABLE ROW LEVEL SECURITY;
CREATE POLICY appointed_contacts_read ON public.appointment_contacts FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.project_appointments a WHERE a.id=appointment_id AND public.can_view_project(a.tenant_id,a.project_id)));
CREATE POLICY appointed_contacts_insert ON public.appointment_contacts FOR INSERT TO authenticated WITH CHECK(EXISTS(SELECT 1 FROM public.project_appointments a JOIN public.client_contacts c ON c.id=contact_id AND c.tenant_id=a.tenant_id AND c.client_id IN(a.contracting_client_id,a.invoicing_client_id) AND c.active WHERE a.id=appointment_id AND public.can_manage_project(a.tenant_id,a.project_id)));
CREATE POLICY appointed_contacts_delete ON public.appointment_contacts FOR DELETE TO authenticated USING(EXISTS(SELECT 1 FROM public.project_appointments a WHERE a.id=appointment_id AND public.can_manage_project(a.tenant_id,a.project_id)));
CREATE FUNCTION public.guard_appointment() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE s jsonb; BEGIN
IF TG_OP='UPDATE' AND (NEW.project_id<>OLD.project_id OR NEW.contracting_client_id<>OLD.contracting_client_id OR NEW.invoicing_client_id<>OLD.invoicing_client_id OR NEW.identity_snapshot IS DISTINCT FROM OLD.identity_snapshot) THEN RAISE EXCEPTION 'APPOINTMENT_ENTITIES_IMMUTABLE'; END IF;
IF TG_OP='INSERT' THEN SELECT jsonb_build_object('contracting_name',c.name,'contracting_legal_name',c.profile->>'legal_name','invoicing_name',i.name,'invoicing_legal_name',i.profile->>'legal_name') INTO NEW.identity_snapshot FROM public.clients c,public.clients i WHERE c.id=NEW.contracting_client_id AND i.id=NEW.invoicing_client_id; END IF;
IF jsonb_typeof(NEW.stages)<>'array' OR jsonb_array_length(NEW.stages)>30 THEN RAISE EXCEPTION 'INVALID_SERVICE_STAGES'; END IF;
FOR s IN SELECT value FROM jsonb_array_elements(NEW.stages) LOOP IF jsonb_typeof(s)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(s) k WHERE k NOT IN('name','scope','starts_on','ends_on')) OR length(btrim(coalesce(s->>'name','')))=0 THEN RAISE EXCEPTION 'INVALID_SERVICE_STAGES'; END IF; IF nullif(s->>'starts_on','')::date> nullif(s->>'ends_on','')::date THEN RAISE EXCEPTION 'INVALID_STAGE_DATES'; END IF; END LOOP;
IF NEW.document_file_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.project_files f JOIN public.project_file_versions v ON v.file_id=f.id AND v.version_no=NEW.document_version WHERE f.id=NEW.document_file_id AND f.project_id=NEW.project_id AND public.project_module_active(f.tenant_id,f.project_id,f.module_id)) THEN RAISE EXCEPTION 'INVALID_APPOINTMENT_DOCUMENT'; END IF; RETURN NEW; END $$;
CREATE TRIGGER appointment_guard BEFORE INSERT OR UPDATE ON public.project_appointments FOR EACH ROW EXECUTE FUNCTION public.guard_appointment();
CREATE FUNCTION public.guard_appointment_terms() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE k text; BEGIN IF jsonb_typeof(NEW.terms)<>'object' THEN RAISE EXCEPTION 'INVALID_APPOINTMENT_TERMS'; END IF; FOR k IN SELECT jsonb_object_keys(NEW.terms) LOOP IF k NOT IN('payment_terms','po_required','po_number','po_status','po_on_invoice','invoice_route','invoice_recipients','supporting_documents','cut_off','submission_instructions','timesheet_process','appointment_basis','framework_reference') OR jsonb_typeof(NEW.terms->k)<>'string' OR length(NEW.terms->>k)>4000 THEN RAISE EXCEPTION 'INVALID_APPOINTMENT_TERMS'; END IF; END LOOP; IF coalesce(NEW.terms->>'po_required','pending') NOT IN('yes','no','pending') OR coalesce(NEW.terms->>'po_on_invoice','pending') NOT IN('yes','no','pending') THEN RAISE EXCEPTION 'INVALID_PO_STATE'; END IF; RETURN NEW; END $$;
CREATE TRIGGER defaults_guard BEFORE INSERT OR UPDATE ON public.client_commercial_defaults FOR EACH ROW EXECUTE FUNCTION public.guard_appointment_terms();
CREATE TRIGGER terms_guard BEFORE INSERT OR UPDATE ON public.appointment_commercials FOR EACH ROW EXECUTE FUNCTION public.guard_appointment_terms();
CREATE FUNCTION public.appointment_contact_details(_appointment uuid) RETURNS TABLE(contact_id uuid,role text,name text,email text,telephone text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT c.id,l.role,c.name,c.email,c.telephone FROM public.appointment_contacts l JOIN public.project_appointments a ON a.id=l.appointment_id JOIN public.client_contacts c ON c.id=l.contact_id WHERE a.id=_appointment AND public.can_view_project(a.tenant_id,a.project_id) $$;
CREATE FUNCTION public.appointment_entity_options(_tenant uuid,_project uuid) RETURNS TABLE(id uuid,name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT c.id,c.name FROM public.clients c WHERE c.tenant_id=_tenant AND c.active AND public.can_manage_project(_tenant,_project) ORDER BY c.name,c.id $$;
CREATE FUNCTION public.appointment_contact_options(_appointment uuid) RETURNS TABLE(id uuid,name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT c.id,c.name FROM public.client_contacts c JOIN public.project_appointments a ON c.tenant_id=a.tenant_id AND c.client_id IN(a.contracting_client_id,a.invoicing_client_id) WHERE a.id=_appointment AND c.active AND public.can_manage_project(a.tenant_id,a.project_id) ORDER BY c.name,c.id $$;
REVOKE ALL ON FUNCTION public.appointment_contact_details(uuid),public.appointment_entity_options(uuid,uuid),public.appointment_contact_options(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.appointment_contact_details(uuid),public.appointment_entity_options(uuid,uuid),public.appointment_contact_options(uuid) TO authenticated,service_role;
CREATE TRIGGER appointments_insert_stamp BEFORE INSERT ON public.project_appointments FOR EACH ROW EXECUTE FUNCTION public.stamp_insert();
CREATE TRIGGER appointments_update_stamp BEFORE UPDATE ON public.project_appointments FOR EACH ROW EXECUTE FUNCTION public.stamp_update();
CREATE TRIGGER appointments_audit AFTER INSERT OR UPDATE ON public.project_appointments FOR EACH ROW EXECUTE FUNCTION public.write_audit('appointment');
CREATE TRIGGER appointment_commercial_insert BEFORE INSERT ON public.appointment_commercials FOR EACH ROW EXECUTE FUNCTION public.stamp_insert();
CREATE TRIGGER appointment_commercial_update BEFORE UPDATE ON public.appointment_commercials FOR EACH ROW EXECUTE FUNCTION public.stamp_update();
CREATE TRIGGER appointment_commercial_audit AFTER INSERT OR UPDATE ON public.appointment_commercials FOR EACH ROW EXECUTE FUNCTION public.write_audit('commercial');
CREATE TRIGGER defaults_insert BEFORE INSERT ON public.client_commercial_defaults FOR EACH ROW EXECUTE FUNCTION public.stamp_insert();
CREATE TRIGGER defaults_update BEFORE UPDATE ON public.client_commercial_defaults FOR EACH ROW EXECUTE FUNCTION public.stamp_update();
CREATE TRIGGER defaults_audit AFTER INSERT OR UPDATE ON public.client_commercial_defaults FOR EACH ROW EXECUTE FUNCTION public.write_audit('commercial');
CREATE TRIGGER appointment_contacts_audit AFTER INSERT OR DELETE ON public.appointment_contacts FOR EACH ROW EXECUTE FUNCTION public.write_audit('appointment');